import Foundation

protocol FavoritesStore {
    func load() -> [Movie]
    func save(_ movies: [Movie])
}

/// Persists favorite movies (full values, in insertion order) as JSON in `UserDefaults`.
struct UserDefaultsFavoritesStore: FavoritesStore {
    // UserDefaults is thread-safe; it just isn't annotated Sendable.
    nonisolated(unsafe) private let defaults: UserDefaults
    private let key: String

    init(defaults: UserDefaults = .standard, key: String = "favorites.movies") {
        self.defaults = defaults
        self.key = key
    }

    func load() -> [Movie] {
        guard let data = defaults.data(forKey: key),
              let movies = try? JSONDecoder.tmdb.decode([Movie].self, from: data) else { return [] }
        return movies
    }

    func save(_ movies: [Movie]) {
        guard let data = try? JSONEncoder().encode(movies) else { return }
        defaults.set(data, forKey: key)
    }
}
